import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..", "..");
const dataDir = join(root, "data");
const outFile = join(__dirname, "..", "data.js");

const banner =
  "// Auto-generated by tools/build-data.js from /data/bills.json, /data/rewards.json\n" +
  "// and Carlos's transaction file. Do not edit by hand: run `npm run build:data`.\n";

const bills = JSON.parse(readFileSync(join(dataDir, "bills.json"), "utf8"));
const rewards = JSON.parse(readFileSync(join(dataDir, "rewards.json"), "utf8"));

/* Carlos owns the transactions. They live at the repo root today and should move
   to /data later, so look in both places and never break whichever is true. */
const txCandidates = [join(dataDir, "transactions.json"), join(root, "mia_transactions.json")];
const txPath = txCandidates.find((p) => existsSync(p));
if (!txPath) {
  console.error("No transaction file found. Looked in:\n  " + txCandidates.join("\n  "));
  process.exit(1);
}
const rawTx = JSON.parse(readFileSync(txPath, "utf8"));
const transactions = Array.isArray(rawTx) ? rawTx : rawTx.transactions || [];

const body = `window.DATA = ${JSON.stringify({ bills, rewards, transactions }, null, 2)};\n`;
const output = banner + body;

const check = process.argv.includes("--check");
if (check) {
  const existing = existsSync(outFile) ? readFileSync(outFile, "utf8") : "";
  if (existing !== output) {
    console.error("web/data.js is out of date. Run `npm run build:data`.");
    process.exit(1);
  }
  console.log("web/data.js is up to date.");
} else {
  writeFileSync(outFile, output, "utf8");
  console.log(
    `Wrote web/data.js (${output.length} bytes) from bills.json, rewards.json and ` +
      `${transactions.length} transactions (${txPath.replace(root, "")})`
  );
}
